   126
   127  void Uart::ReceiveTask(const uint8_t *aBuf, uint16_t aBufLength)
   128  {
   129  #if !OPENTHREAD_CONFIG_UART_CLI_RAW
   130      static const char sEraseString[] = {'\b', ' ', '\b'};
   131      static const char CRNL[]         = {'\r', '\n'};
   132  #endif
   133      static const char sCommandPrompt[] = {'>', ' '};
   134      const uint8_t *   end;
   135
   136      end = aBuf + aBufLength;
   137
   138      for (; aBuf < end; aBuf++)
   139      {
   140          switch (*aBuf)
   141          {
   142          case '\r':
   143          case '\n':
   144  #if !OPENTHREAD_CONFIG_UART_CLI_RAW
   145              Output(CRNL, sizeof(CRNL));
   146  #endif
   147              if (mRxLength > 0)
   148              {
   149                  mRxBuffer[mRxLength] = '\0';
   150                  ProcessCommand();
   151              }
   152
   153              Output(sCommandPrompt, sizeof(sCommandPrompt));
   154
   155              break;
   156
   157  #if !OPENTHREAD_CONFIG_UART_CLI_RAW
   158  #if OPENTHREAD_POSIX
   159
   160          case 0x04: // ASCII for Ctrl-D
   161              exit(EXIT_SUCCESS);
   162              break;
   163  #endif
   164
   165          case '\b':
   166          case 127:
   167              if (mRxLength > 0)
   168              {
