   338  int Interpreter::Hex2Bin(const char *aHex, uint8_t *aBin, uint16_t aBinLength)
   339  {
   340      size_t      hexLength = strlen(aHex);
   341      const char *hexEnd    = aHex + hexLength;
   342      uint8_t *   cur       = aBin;
   343      uint8_t     numChars  = hexLength & 1;
   344      uint8_t     byte      = 0;
   345      int         rval;
   346
   347      VerifyOrExit((hexLength + 1) / 2 <= aBinLength, rval = -1);
   348
   349      while (aHex < hexEnd)
   350      {
   351          if ('A' <= *aHex && *aHex <= 'F')
   352          {
   353              byte |= 10 + (*aHex - 'A');
   354          }
   355          else if ('a' <= *aHex && *aHex <= 'f')
   356          {
   357              byte |= 10 + (*aHex - 'a');
   358          }
   359          else if ('0' <= *aHex && *aHex <= '9')
   360          {
   361              byte |= *aHex - '0';
   362          }
   363          else
   364          {
   365              ExitNow(rval = -1);
   366          }
   367
   368          aHex++;
   369          numChars++;
   370
   371          if (numChars >= 2)
   372          {
   373              numChars = 0;
   374              *cur++   = byte;
   375              byte     = 0;
   376          }
   377          else
   378          {
   379              byte <<= 4;
   380          }
   381      }
   382
   383      rval = static_cast<int>(cur - aBin);
   384
   385  exit:
   386      return rval;
   387  }
